def fm(e,v,u,a=()):return dict(expression=e,variables=v,units=u,assumptions=list(a))
def ask(p,tag,loc,stem,answers,*,kind='conceptual',difficulty='easy',ass=(),steps=(),formulas=(),cites=(),ck='statement',conflict=None,primary=(),correct=(0,)):
 cid=f'{B}-C-{tag}';c=CM[cid];qid=f'{B}-P{p}-Q{1+sum(q["id"].startswith(f"{B}-P{p}-Q")for q in Q):02}'
 opts=[x[0]for x in answers];why=[x[1]for x in answers];assert len(opts)==len(set(opts))
 cc=[dict(slideId=f'lectures-p{pg}',sourceId='lectures',sourceSha256=SHA,physicalPage=pg,kind=k,locator=f'Printed slide {pg-1619}: {l}',evidenceText=T[pg],role='conflict'if conflict and pg==conflict['physicalPage']else'premise'if kind in ['numerical','synthesis','algorithm_trace']else'explicit',region=None)for pg,k,l in [(p,ck,loc)]+list(cites)]
 idx=list(range(len(opts)));random.Random(qid).shuffle(idx);mapping={old:f'o{n+1}'for n,old in enumerate(idx)};just=' '.join(why[i]for i in correct)
 q=dict(id=qid,version=1,status='draft',authorId=A,stem=stem,selectionMode='multi'if len(correct)>1 else'single',type=kind,difficulty=difficulty,cognitiveSkill='numerical'if kind=='numerical'else'algorithm'if kind=='algorithm_trace'else'synthesis'if kind=='synthesis'else'application'if kind in ['scenario','diagram']else'recall'if kind=='definition'else'conceptual',week=11,lectureId='L52',topic='Sensors used in Robots',subtopic=c['title'],tags=['sensors',tag],conceptIds=[cid],assumptions=list(ass),options=[dict(id=mapping[i],text=opts[i])for i in idx],correctOptionIds=[mapping[i]for i in correct],citations=cc,solution=dict(justification=just,optionExplanations={mapping[i]:('Correct. 'if i in correct else'Incorrect. ')+why[i]for i in idx},steps=list(steps),formulas=list(formulas),simpleExplanation=just,memoryAid=None,misconceptions=[why[i]for i in range(len(opts))if i not in correct],examTraps=[],prerequisiteConceptIds=[]),origin='generated',reviewIds=[])
 if len(opts)<4:q['optionCountRationale']='Three distinct technical alternatives avoid unrelated filler.'
 if conflict:
  q['conflictResolution']=dict(status='explicit-qualification-pending-independent-review',questionVersion=1,sourceId='lectures',sourceSha256=SHA,physicalPage=conflict['physicalPage'],sourceClaim=conflict['finding'],basis=conflict['handling'],method=conflict['method'],sourceIssueId=conflict['id'],scope='This version only; independent review required.');primary=list(primary)+conflict['primaryEvidence']
 if primary:q['primaryEvidence']=list(primary)
 Q.append(q);c['questionIds'].append(qid);c['status']='drafted';return q
