ask(1683,'sensor-selection','Measurement need and operating environment','A task needs range0.1–3m, error≤2cm and at least20updates/s. Which supplied candidate meets all three numerical constraints?', [('Range0.05–4m,error1cm,rate25Hz','Its range covers the full task interval, error is below the maximum and rate exceeds the minimum.'),('Range0.2–6m,error1cm,rate30Hz','It misses the required0.1–0.2m interval.'),('Range0.05–4m,error1cm,rate10Hz','It fails the update-rate requirement.'),('Range0.05–4m,error3cm,rate25Hz','It fails the error bound.')],kind='scenario',ass=['All candidates otherwise meet the same environment/interface requirements; quoted error bounds are applicable and trustworthy.'])
ask(1683,'sensor-selection','Latency budget andedge/cloud inference','A supplied pipeline budget is50ms. Sensing takes10ms, transfer5ms and control5ms. What inference time remains?', [('30ms','50−10−5−5=30ms.'),('40ms','This subtracts sensing only and omits transfer/control.'),('20ms','This counts one of the supplied10ms costs twice.')],kind='numerical',ass=['Stages are sequential, with no additional overhead or overlap; budget is end-to-end.'],steps=['Sum non-inference costs10+5+5=20ms.','Subtract from50ms.'],formulas=[fm('T_infer≤T_budget−T_sense−T_transfer−T_control',{'T_infer':'Allowed inference duration','T_budget':'End-to-end latency limit','T_sense':'Sensing duration','T_transfer':'Transfer duration','T_control':'Control processing duration'},{'T_infer,T_budget,T_sense,T_transfer,T_control':'ms'},['Sequential nonoverlapping stages; no omitted overhead; nonnegative remainder.'])])
ask(1683,'sensor-selection','SWaP andendurance','With a supplied usable battery energy of100Wh, other loads of15W and sensors drawing5W, what ideal constant-load endurance results?', [('5h','100Wh/(15+5)W=5h.'),('20h','This counts sensor power alone and omits other loads.'),('6.67h','This omits the sensor load.')],kind='numerical',ass=['Constant total power; energy already usable after any battery limitations; no further losses or reserve.'],steps=['Total power15+5=20W.','Divide100Wh by20W.'],formulas=[fm('T=E/(P_other+P_sensors)',{'T':'Ideal endurance','E':'Usable battery energy','P_other':'Other power demand','P_sensors':'Total sensor power demand'},{'T':'h','E':'Wh','P_other,P_sensors':'W'},['Constant positive total load; usable energy already accounts for losses/reserve.'])])
