ask(1623,'sensor-role','Perception/control/safety/learning/localization/manipulation role list','Which grouping correctly distinguishes three roles beyond simple logging?', [('Perception interprets observations; feedback uses measured error; learning can use recorded examples','The same sensing stream may support interpretation, control and model training through different processing.'),('Perception necessarily changes motor commands; feedback only archives data; learning needs no observations','These confuse active feedback with storage and remove learning evidence.'),('Safety is guaranteed by connecting a sensor; localization directly identifies every object class','Sensor connection alone does not validate safety, and localization concerns pose rather than every semantic label.')],kind='match')
ask(1630,'encoder','Four-track binary labels0111and1000','In the drawn binary labeling, how many bits change from0111 to1000, and what does this imply about calling the disk Gray-coded?', [('Four bits change; the shown labeling is not a one-bit Gray transition','All four positions differ between the two supplied words.'),('One bit changes; every absolute encoder necessarily uses Gray code','Absolute encoding does not imply Gray code, and the displayed words differ in four positions.'),('Three bits change; the leading bit is not part of the angular code','The leading bit is one of the four shown tracks.')],kind='algorithm_trace',ck='figure',ass=['Use the actual four binary code positions; compare these two printed adjacent codes, not a different disk.'],steps=['Compare0to1,1to0,1to0,1to0.','Count four changed positions.','A Gray-code adjacency would change one bit.'],formulas=[fm('H(a,b)=Σ_i 1[a_i≠b_i]',{'H':'Hamming distance between code words','a_i,b_i':'Corresponding binary bits','i':'Bit-position index'},{'H':'bits changed','a_i,b_i,i':'dimensionless'},['Equal-length binary words; all four positions counted.'])])
