ask(1642,'tilt','Ball contact working principle','A mounted ball switch changes state during a strong linear acceleration without an intentional rotation. Which interpretation is most defensible?', [('Contact state can respond to effective loading as well as orientation; it is not a unique continuous angle reading','The ball’s position depends on forces, so dynamic acceleration complicates an orientation-only inference.'),('The contact proves an exact gravity-referenced angle independent of acceleration','A binary mechanical state cannot supply that unique angle under the supplied disturbance.'),('Any change without commanded rotation must be a software syntax error','Physical motion/loading can change a valid contact reading.')],kind='scenario',ass=['The acceleration is large enough to affect the freely moving ball; no claim about a specific switch threshold.'])
ask(1647,'reed-code','Level-polling loop without debounce','During one magnet passage, contact bounce causesLOW→HIGH→LOW→HIGH→LOW before reopening. What would a naive falling-edge counter record, and why is debounce needed?', [('Three falling edges although there was one passage; debounce should consolidate the event','Three entries intoLOW can arise from one physical encounter.'),('One falling edge automatically because INPUT_PULLUP performs debouncing','The pull-up does not supply a temporal debounce filter.'),('Zero falling edges because only rising transitions can be detected in software','Either polarity of transition can be detected by comparing consecutive states.')],kind='algorithm_trace',ck='code',ass=['Initial stateHIGH; each transition is sampled; a separate naive HIGH-to-LOW counter is an explicitly supplied extension, not present in the printed program.'],steps=['InitialHIGHtofirstLOW is one falling edge.','Each subsequentHIGHtoLOW adds another edge.','Totalthree counts must not be equated with three magnet passages.'],formulas=[fm('N_fall=Σ_k 1[s_(k−1)=HIGH and s_k=LOW]',{'N_fall':'Detected falling-edge count','s_k':'Sampled digital state at stepk','k':'Sample index'},{'N_fall':'events','s_k':'logic level','k':'dimensionless'},['All stated transitions sampled; no debounce or missed samples.'])])
ask(1661,'imu-code','Two Wire.read calls in one bitwise-OR expression','Which change explicitly makes the intended high-byte-then-low-byte acquisition order clear and portable?', [('Read high and low bytes into separate variables in separate statements, then combine them','This sequences the stream reads before bit assembly.'),('Keep the two reads in one bitwise-OR expression and assume source text order guarantees evaluation order','That is not a portable ordering guarantee for these operands.'),('Exchange the OR operator for addition while keeping the two stream reads unsequenced','Changing the arithmetic operator alone does not establish the required read sequence.')],kind='algorithm_trace',ck='code',steps=['Validate that the required bytes are available.','Read high byte, then low byte, in separate statements.','Combine the stored values using a sufficiently wide unsigned intermediate and interpret signed data.'],conflict=IMUCODE)
ask(1682,'force-torque','Capacitive F/T deflection mechanism','For an explicitly supplied ideal parallel-plate modelC=εA/g, what happens to capacitance when deflection reduces gapg by half, withεandA fixed?', [('It doubles','C is inversely proportional to the positive plate gap.'),('It halves','That would follow a direct rather than inverse gap dependence.'),('It stays fixed because area is unchanged','Gap also appears in the denominator.')],kind='numerical',ass=['Supplied ideal model, not a complete commercial sensor calibration; constant overlap area/permittivity, positive gap, negligible fringing.'],steps=['Replaceg byg/2.','C_new=εA/(g/2)=2C_old.'],formulas=[fm('C=εA/g; C_new/C_old=g_old/g_new',{'C,C_new,C_old':'Capacitance','ε':'Dielectric permittivity','A':'Plate overlap area','g,g_old,g_new':'Positive plate separation'},{'C,C_new,C_old':'F','ε':'F/m','A':'m²','g,g_old,g_new':'m'},['Parallel plates; negligible fringing; fixedAandε; no contact.'])])
ask(1683,'sensor-selection','Range, accuracy, response time and power selection bullets','A supplied design requires coverage of 0.1–3 m, error at most 2 cm, a sequential loop no longer than 50 ms, and at least 5 h from 120 Wh usable energy. Other loads draw 18 W; transfer plus control takes 10 ms per loop. Which candidate meets every requirement?', [('Range 0.05–4 m; error 1 cm; sensing 10 ms; inference 30 ms; sensor power 5 W','The range includes the required interval, error is acceptable, total time is 50 ms and endurance is 120/23≈5.22 h.'),('Range 0.2–6 m; error 1 cm; sensing 5 ms; inference 20 ms; sensor power 3 W','Time is 35 ms and endurance is about 5.71 h, but the required 0.1–0.2 m near region is outside coverage.'),('Range 0.05–4 m; error 1 cm; sensing 10 ms; inference 30 ms; sensor power 8 W','Range, error and 50 ms timing pass, but 120/26≈4.62 h fails the endurance requirement.'),('Range 0.05–4 m; error 1 cm; sensing 15 ms; inference 30 ms; sensor power 4 W','Range, error and about 5.45 h endurance pass, but 15+30+10=55 ms exceeds the loop budget.')],kind='synthesis',difficulty='medium',ass=['All candidate figures and requirements are supplied, not product claims. Sequential processing without overlap; constant loads; usable energy already accounts for battery losses; error bounds apply across each candidate range.'],steps=['Check that each candidate covers both required range endpoints and satisfies the error limit.','Add sensing, inference, transfer and control times for a sequential loop.','Add sensor power to the 18 W other load.','Divide usable energy by total power, then apply all constraints together.'],formulas=[fm('r_min≤r_required,min; r_max≥r_required,max; e_max≤e_required',{'r_min,r_max':'Candidate range endpoints','r_required,min,r_required,max':'Required range endpoints','e_max':'Candidate maximum absolute error','e_required':'Allowed maximum absolute error'},{'r_min,r_max,r_required,min,r_required,max':'m','e_max,e_required':'cm'},['Bounds use the same physical range definition; error applies across the stated range.']),fm('T_loop=T_sense+T_infer+T_transfer+T_control',{'T_loop':'Complete loop duration','T_sense':'Acquisition time','T_infer':'Inference time','T_transfer':'Transfer time','T_control':'Control time'},{'T_loop,T_sense,T_infer,T_transfer,T_control':'ms'},['Sequential non-overlapping stages; supplied durations.']),fm('t_endurance=E_usable/(P_other+P_sensor)',{'t_endurance':'Ideal operating duration','E_usable':'Usable battery energy','P_other':'All non-sensor load power','P_sensor':'Candidate sensor power'},{'t_endurance':'h','E_usable':'Wh','P_other,P_sensor':'W'},['Constant positive total load; no double-counting of losses already included in usable energy.'])])
